huayuWallCoordinates:
function huayuWallCoordinates(element) {
  return (element?.geometry || []).map((point) => [Number(point.lon), Number(point.lat)])
    .filter(([longitude, latitude]) => Number.isFinite(longitude) && Number.isFinite(latitude));
}

huayuWallJoinRings:
function huayuWallJoinRings(segments) {
  const remaining = segments.filter((coordinates) => coordinates.length >= 2)
    .map((coordinates) => coordinates.slice());
  const rings = [];
  while (remaining.length) {
    const ring = remaining.shift();
    while (ring.length >= 2 && huayuWallPointKey(ring[0]) !== huayuWallPointKey(ring.at(-1))) {
      const endKey = huayuWallPointKey(ring.at(-1));
      const nextIndex = remaining.findIndex((coordinates) => (
        huayuWallPointKey(coordinates[0]) === endKey || huayuWallPointKey(coordinates.at(-1)) === endKey
      ));
      if (nextIndex < 0) break;
      const next = remaining.splice(nextIndex, 1)[0];
      if (huayuWallPointKey(next.at(-1)) === endKey) next.reverse();
      ring.push(...next.slice(1));
    }
    if (ring.length >= 4 && huayuWallPointKey(ring[0]) === huayuWallPointKey(ring.at(-1))) rings.push(ring);
  }
  return rings;
}

huayuWallRingArea:
function huayuWallRingArea(ring) {
  let area = 0;
  for (let index = 1; index < ring.length; index += 1) {
    area += ring[index - 1][0] * ring[index][1] - ring[index][0] * ring[index - 1][1];
  }
  return area / 2;
}

huayuNormalizedWallRing:
function huayuNormalizedWallRing(ring, inner) {
  const coordinates = ring.slice();
  const clockwise = huayuWallRingArea(coordinates) < 0;
  if (clockwise !== inner) coordinates.reverse();
  return coordinates;
}

huayuWallPointInRing:
function huayuWallPointInRing(point, ring) {
  let inside = false;
  for (let current = 0, previous = ring.length - 1; current < ring.length; previous = current, current += 1) {
    const [currentX, currentY] = ring[current];
    const [previousX, previousY] = ring[previous];
    const intersects = ((currentY > point[1]) !== (previousY > point[1]))
      && point[0] < ((previousX - currentX) * (point[1] - currentY))
        / (previousY - currentY || Number.EPSILON) + currentX;
    if (intersects) inside = !inside;
  }
  return inside;
}

huayuCityWallRelationGeometry:
function huayuCityWallRelationGeometry(relation, waysById) {
  const outerSegments = [];
  const innerSegments = [];
  (relation.members || []).forEach((member) => {
    if (member.type !== "way") return;
    const coordinates = huayuWallCoordinates(waysById.get(String(member.ref)));
    if (coordinates.length < 2) return;
    (member.role === "inner" ? innerSegments : outerSegments).push(coordinates);
  });
  const outerRings = huayuWallJoinRings(outerSegments)
    .map((ring) => huayuNormalizedWallRing(ring, false));
  const innerRings = huayuWallJoinRings(innerSegments)
    .map((ring) => huayuNormalizedWallRing(ring, true));
  if (!outerRings.length) return null;
  const polygons = outerRings.map((ring) => [ring]);
  innerRings.forEach((ring) => {
    const sample = ring[0];
    let polygonIndex = -1;
    let polygonArea = Infinity;
    outerRings.forEach((outerRing, index) => {
      const area = Math.abs(huayuWallRingArea(outerRing));
      if (area < polygonArea && huayuWallPointInRing(sample, outerRing)) {
        polygonIndex = index;
        polygonArea = area;
      }
    });
    if (polygonIndex >= 0) polygons[polygonIndex].push(ring);
  });
  return polygons.length === 1
    ? { type: "Polygon", coordinates: polygons[0] }
    : { type: "MultiPolygon", coordinates: polygons };
}
